pub(super) fn p2p3_assurance_reports__metric_value(
    mut product_metrics: Value,
    mut metric_id: Value,
) -> Result<Value> {
    for current in sequence(&get(
        &product_metrics,
        &json!("metrics"),
        Value::Array(vec![]),
    ))? {
        let mut item = current;
        if equal(&get(&item, &json!("metric_id"), Value::Null), &metric_id) {
            return Ok(get(&item, &json!("value"), Value::Null));
        }
    }
    return Ok(Value::Null);
}
